/**
 * @summary Get a quick view summary for an accessible profile
 */
export type getProfileSummaryResponse = {
  data: GetProfileSummary200;
  status: number;
}

export const getGetProfileSummaryUrl = (params: GetProfileSummaryParams,) => {

  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value === null) {
      normalizedParams.append(key, 'null');
    } else if (value !== undefined) {
      normalizedParams.append(key, value.toString());
    }
  });

  return `/api/v1/profiles/summary?${normalizedParams.toString()}`
}

export const getProfileSummary = async (params: GetProfileSummaryParams, options?: RequestInit): Promise<getProfileSummaryResponse> => {
return customFetch<Promise<getProfileSummaryResponse>>(getGetProfileSummaryUrl(params),
  {      
    ...options,
    method: 'GET'
    
  }
);}


